from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

prs = Presentation('/root/input.pptx')

print("=== Slides and Shapes ===")
for slide_idx, slide in enumerate(prs.slides, 1):
    print(f"\nSlide {slide_idx}:")
    for shape_idx, shape in enumerate(slide.shapes, 1):
        shape_type = shape.shape_type
        print(f"  Shape {shape_idx}: type={shape_type}, name='{shape.name}'")

        # Check if it has text
        if shape.has_text_frame:
            text = ""
            for para in shape.text_frame.paragraphs:
                for run in para.runs:
                    text += run.text
            if text.strip():
                print(f"    Text: '{text}'")

        # Check for OLE object
        if hasattr(shape, 'ole_format'):
            print(f"    OLE Object: {shape.ole_format}")
EOF
